    """Tidy up a hand-typed label: surrounding blanks removed, upper case, runs of blanks/underscores/dots turned into
    the separator and, inside the digit groups only, the letter O read as 0."""
    t = re.sub(r"[ _.]+", SEP, text.strip().upper())
    if not t:
        return t
    parts = t.split(SEP)
    if len(parts) == 4:
        parts = [parts[0]] + [re.sub('O', '0', p) for p in parts[1:3]] + [parts[3]]
