        raise LabelError(f"bad month: {month}")
    if not 1 <= seq <= SEQ_MAX:
        raise LabelError(f"bad sequence number: {seq}")
    body = f"{year % 100:02d}{month:02d}{seq:04d}"
    return f"{prefix}{SEP}{body[:4]}{SEP}{body[4:]}{SEP}{check_char(body)}"


